test('wrong auth subject closes known tokens, keeps failed journal, logs no credentials and refuses rerun',async()=>{
 let journal:string|null=null,logins=0,logouts=0,calls=0;const v=input(),deps={load:async()=>journal,append:async(line:string)=>{journal=(journal??'')+line},verifyGate:async()=>{},readPrior:async()=>({previous:{registers:{},downloads:{}},old:{legacy:{}}}),fetch:(async(url:any)=>{calls++;const u=String(url);if(u===HOST+'/ready')return Response.json({status:'ready',schemaVersion:21,profile:'neuvetra.private-synthetic-staging.v1',legacyContainmentVerified:true});if(u===HOST+'/workspace-api/config')return Response.json({profile:'neuvetra.private-synthetic-staging.v1',supabaseUrl:AUTH,anonKey:v.env.SUPABASE_ANON_KEY},{headers:{'cache-control':'no-store'}});if(u.includes('/auth/v1/token')){logins++;return Response.json({access_token:'private-token-'+logins,user:{id:logins===1?v.accounts[0]!.id:'wrong-subject'}})}if(u.includes('/auth/v1/logout')){logouts++;return new Response(null,{status:204})}throw Error('Unexpected network')})as unknown as typeof fetch}
 const result=await runM78Journey(parseM78JourneyInput(v),deps);expect(result.status).toBe('failed');expect(result.allCreatedAuthSessionsClosed).toBe(true);expect(logins).toBe(2);expect(logouts).toBe(2);expect(journal).not.toContain('synthetic-private-marker');expect(journal).not.toContain('private-token');expect(journal).not.toContain('@synthetic.invalid');const before=calls;expect((await runM78Journey(parseM78JourneyInput(v),deps)).status).toBe('failed');expect(calls).toBe(before)
})

test('legacy audit append failures preserve all known session cleanup and refuse success',async()=>{
 for(const failure of ['login_outcome','logout_intent']){let logins=0,logouts=0,failedOnce=false;const logged:any[]=[]
  const helper=(async(_input:any,deps:any)=>{const tokens:string[]=[];try{for(let i=0;i<4;i++){const r=await deps.fetch(AUTH+'/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({password:'secret-password',email:'private@synthetic.invalid'})});tokens.push((await r.json()).access_token)}}finally{for(const token of tokens)await deps.fetch(AUTH+'/auth/v1/logout?scope=local',{method:'POST',headers:{authorization:'Bearer '+token}})}await deps.save({baseline:{synthetic:true}});return {status:'passed',allCreatedAuthSessionsClosed:true,applicationPostRequests:0}})as any
  const result=await readM78Legacy(parseM78JourneyInput(input()),{synthetic:true},async(url)=>{if(url.includes('/token?')){logins++;return Response.json({access_token:'secret-token-'+logins})}logouts++;return new Response(null,{status:204})},async(kind,data)=>{logged.push({kind,data});if(!failedOnce&&(failure==='login_outcome'?kind==='legacy_auth_outcome'&&data.action==='login':kind==='legacy_auth_intent'&&data.action==='logout')){failedOnce=true;throw Error('Injected durable append failure')}},helper)
  expect(failedOnce).toBe(true);expect(result.verified).toBe(false);expect(result.allCreatedAuthSessionsClosed).toBe(true);expect(logins).toBe(4);expect(logouts).toBe(4);expect(JSON.stringify(logged)).not.toContain('secret-');expect(JSON.stringify(logged)).not.toContain('@synthetic.invalid')
 }
})
test('production predecessor verifier rejects invented or absent journal bytes',()=>{for(const text of ['', '{}\n','synthetic-pinned-substitute'])expect(()=>acceptedM77(text,company)).toThrow()})

test('UTF8 event budgets bound the fixed three-phase journal below128MB',()=>{const caps={terminal:2*m78JournalEventLimit('baseline'),requests:41*m78JournalEventLimit('post_intent'),verified:38*m78JournalEventLimit('post_verified'),other:164*m78JournalEventLimit('post_outcome')};expect(Object.values(caps).reduce((a,b)=>a+b,0)).toBe(119668000);expect(Object.values(caps).reduce((a,b)=>a+b,0)).toBeLessThan(128000000);const es=closedJournal();const bad=es.find(e=>e.kind==='post_verified')!;bad.data.padding='x'.repeat(4001);const fixed:M78Event[]=[];for(const e of es)add(fixed,e.mode,e.kind,e.data);expect(()=>readM78Journal(fixed.map(e=>JSON.stringify(e)).join('\n')+'\n',company)).toThrow()})

test('fully rehashed durable evidence still refuses foreign routes and invented verification identities',()=>{for(const mutate of [(es:M78Event[])=>{for(const e of es.filter(e=>['post_intent','post_outcome'].includes(e.kind)&&e.data.name==='step_0'))e.data.route='/workspace-api/workspace/'+company+'/members'},(es:M78Event[])=>{for(const e of es.filter(e=>['post_intent','post_outcome'].includes(e.kind)&&e.data.name==='step_0'))e.data.route='/workspace-api/workspace/78000000-0000-4000-8000-000000000099/scope1-inventory'},(es:M78Event[])=>es.find(e=>e.kind==='post_verified')!.data.verifiedIdentity={id:company,companyId:'78000000-0000-4000-8000-000000000099'},(es:M78Event[])=>es.find(e=>e.kind==='post_verified')!.data.verifiedIdentity={id:company,invented:'value'},(es:M78Event[])=>es.find(e=>e.kind==='post_verified')!.data.name='m78_member_write_refused']){const es=closedJournal();mutate(es);const rebuilt:M78Event[]=[];for(const e of es)add(rebuilt,e.mode,e.kind,e.data);const bytes=rebuilt.map(e=>JSON.stringify(e)).join('\n')+'\n';expect(()=>cleanM78Journal(readM78Journal(bytes,company))).toThrow()}})
